            for h in range(minh,H-r0+1):
                for w in range(minw,W-c0+1):
                    r1,c1=r0+h-1,c0+w-1
                    if all(mask[y][x] for y in range(r0,r1+1) for x in range(c0,c1+1)):
                        # maximal if cannot extend up/left/down/right
                        ext=False
                        if r0>0 and all(mask[y-1][x] for x in range(c0,c1+1)): ext=True
                        elif c0>0 and all(mask[y][x-1] for y in range(r0,r1+1)): ext=True
                        elif r1<H-1 and all(mask[y+1][x] for x in range(c0,c1+1)): ext=True
                        elif c1<W-1 and all(mask[y][x+1] for y in range(r0,r1+1)): ext=True
