def zcomps(gin):
    from collections import deque
    seen=set(); out=[]
    for y in range(len(gin)):
        for x in range(len(gin[0])):
            if gin[y][x]==0 and (y,x) not in seen:
                q=[(y,x)]; seen.add((y,x)); c=[]
                while q:
                    p=q.pop(); c.append(p)
