def comps8(g,val=0):
    seen=set(); out=[]
    for y in range(len(g)):
        for x in range(len(g[0])):
            if g[y][x]==val and (y,x) not in seen:
                q=[(y,x)]; seen.add((y,x)); cc=[(y,x)]
                while q:
                    a,b=q.pop()
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            n=(a+dy,b+dx)
                            if 0<=n[0]<len(g) and 0<=n[1]<len(g[0]) and g[n[0]][n[1]]==val and n not in seen:
                                seen.add(n); q.append(n); cc.append(n)
                out.append(cc)
    return out
