def solve(I):
    H,W=len(I),len(I[0])
    vals=collections.Counter(v for row in I for v in row); bg=vals.most_common(1)[0][0]
    # flood bg from border through bg only
    seen=[[False]*W for _ in range(H)]; q=deque()
    for y in range(H):
        for x in (0,W-1):
            if I[y][x]==bg and not seen[y][x]: seen[y][x]=True;q.append((y,x))
    for x in range(W):
        for y in (0,H-1):
            if I[y][x]==bg and not seen[y][x]: seen[y][x]=True;q.append((y,x))
    while q:
        y,x=q.popleft()
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            s=(y+dy,x+dx)
            if 0<=s[0]<H and 0<=s[1]<W and not seen[s[0]][s[1]] and I[s[0]][s[1]]==bg:
                seen[s[0]][s[1]]=True;q.append(s)
    enc={(y,x) for y in range(H) for x in range(W) if I[y][x]==bg and not seen[y][x]}
    O=[row[:] for row in I]
    if enc:
        newcol=O[next(iter(enc))[0]][next(iter(enc))[1]] or None
        # find surrounding color: most common neighbor color adjacent to enc region
        nb=collections.Counter()
        for y,x in enc:
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                s=(y+dy,x+dx)
                if 0<=s[0]<H and 0<=s[1]<W and I[s[0]][s[1]]!=bg: nb[I[s[0]][s[1]]]+=1
        tgt=nb.most_common(1)[0][0]
        print('enc size',len(enc),'-> color',tgt)
        for y,x in enc: O[y][x]=tgt
    return O,bg
for d in [1,2,3,4,5,6,7,8]:
    I=G[f'Demo pair {d} input']; O_=G[f'Demo pair {d} output']
    O,bg=solve(I)
    print(d,'bg=',bg,'pred==out?',O==O_)

