from collections import Counter,deque
def f(I):
    H,W=len(I),len(I[0])
    # fill color = the rare color appearing exactly 3 times
    cnt=Counter(v for row in I for v in row)
    fill=[k for k,v in cnt.items() if v==3][0]
    seen=[[False]*W for _ in range(H)]; out=[row[:] for row in I]
    for r in range(H):
        for c in range(W):
            if I[r][c]!=0 and not seen[r][c]:
                q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da in (-1,0,1):
                        for db in (-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and not seen[x][y] and I[x][y]!=0:
                                seen[x][y]=True; q.append((x,y))
                if len(cells)>=4: continue
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                hgt=max(rs)-min(rs)+1; wid=max(cs)-min(cs)+1
                if (hgt>=3 or wid>=3) and hgt>wid and wid==2:
                    colA=min(rs); colB=max(rs)
                    c0=min(cs)
                    for i in range(hgt-2):
                        out[colA+i][c0]=fill; out[colB+i][c0]=fill
                        out[colA+i][c0+1]=fill; out[colB+i][c0+1]=fill
                else:
                    for j in range(wid-2):
                        out[min(cs)][colA+j]=fill; out[min(cs)][colB+j]=fill
                        out[max(cs)][colA+j]=fill; out[max(cs)][colB+j]=fill
    return out
